urlset:
{%- for post in posts -%}
  {%- if post.layout == 'post' -%} 

  https://blog.flwolfy.xyz/{{ post.path | uriencode }}
  {% if post.updated %}
  {{ post.updated.toISOString() }}
  {% elif post.date %}
  {{ post.date.toISOString() }}
  {% endif %}
  monthly
  0.6

  {%- endif -%}
{%- endfor -%}
